586	"use client";
587	
588	import ShapeWaves from "@/components/ShapeWaves";
589	
590	export default function HomeBackground({ quiet = false, onIntroComplete }: { quiet?: boolean; onIntroComplete?: () => void }) {
591	  return (
592	    <div aria-hidden="true" className={`relative h-full overflow-hidden transition-opacity duration-700 motion-reduce:transition-none ${quiet ? "opacity-60" : ""}`}>
593	      <ShapeWaves
594	        fontFamily={'Geist, "Geist Sans", system-ui, sans-serif'}
595	        fontWeight={500}
596	        textSize={0.6}
597	        shapes="mixed"
598	        cellSize={8}
599	        dotSize={0.75}
600	        color="#705252"
601	        hoverColor="#ffffff"
602	        backgroundColor="#362a4a"
603	        speed={quiet ? 0.25 : 2.2}
604	        scale={1}
605	        contrast={1.9}
606	        brightness={0.64}
607	        flow={0}
608	        direction={200}
609	        fade={0}
610	        interactive={false}
611	        splashRadius={40}
612	        splashStrength={1.35}
613	        glow={0.8}
614	        intro
615	        introDuration={1.2}
616	        onIntroComplete={onIntroComplete}
617	        onError={onIntroComplete}
618	        paused={false}
619	        swimmingWorm={!quiet}
620	      />
621	    </div>
622	  );
623	}
624	"use client";
625	
626	import { useEffect, useRef } from "react";
627	import { Group, Mesh, MeshPhysicalMaterial, OrthographicCamera, PMREMGenerator, Scene, TorusGeometry, Vector3, WebGLRenderer } from "three";
628	import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
629	import { RoomEnvironment } from "three/addons/environments/RoomEnvironment.js";
630	import { createWormPreview } from "@/lib/worm-preview";
631	
632	export default function PetriDish({ onReady, playing }: { onReady: (ready: boolean) => void; playing: boolean }) {
633	  const canvasRef = useRef<HTMLCanvasElement>(null);
634	  const playingRef = useRef(playing);
635	  const updatePlaybackRef = useRef(() => {});
636	
637	  useEffect(() => {
638	    playingRef.current = playing;
639	    updatePlaybackRef.current();
640	  }, [playing]);
641	
642	  useEffect(() => {
643	    let cleanup: (() => void) | undefined;
644	    // Let Strict Mode cancel its trial effect before allocating a second GPU renderer.
645	    const startFrame = requestAnimationFrame(() => {
646	      const canvas = canvasRef.current!;
647	      let renderer: WebGLRenderer;
648	      try {
649	        renderer = new WebGLRenderer({ canvas, alpha: true, antialias: true });
650	      } catch {
651	        onReady(true);
652	        return;
653	      }
654	
655	      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
656	      const scene = new Scene();
657	      const plate = new Group();
658	      // The source lies in XY: present its face 30° above horizontal toward the camera.
659	      plate.rotation.x = -Math.PI / 3;
660	      scene.add(plate);
661	      const rim = new Mesh(new TorusGeometry(0.985, 0.012, 12, 128), new MeshPhysicalMaterial({
662	        color: getComputedStyle(canvas).getPropertyValue("--color-foreground").trim(),
663	        transparent: true, opacity: 0.6, roughness: 0.2, clearcoat: 1, depthWrite: false,
664	      }));
665	      const preview = createWormPreview();
666	      const worm = new Mesh(preview.geometry, new MeshPhysicalMaterial({
667	        color: getComputedStyle(canvas).getPropertyValue("--color-accent").trim(),
668	        roughness: 0.35,
669	        clearcoat: 0.4,
670	      }));
671	      const camera = new OrthographicCamera(-1.2, 1.2, 0.8, -0.8, 0.1, 10);
672	      camera.position.z = 4;
673	      const room = new RoomEnvironment();
674	      const pmrem = new PMREMGenerator(renderer);
675	      const environment = pmrem.fromScene(room, 0.04);
676	      scene.environment = environment.texture;
677	      room.dispose();
678	      pmrem.dispose();
679	
680	      let disposed = false;
681	      let prepared = false;
682	      let dish: Mesh | undefined;
683	      const disposeDish = (mesh: Mesh) => {
684	        mesh.geometry.dispose();
685	        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
686	        materials.forEach(material => material.dispose());
687	      };
688	      const render = () => renderer.render(scene, camera);
689	      const resize = () => {
690	        const { width, height } = canvas.getBoundingClientRect();
691	        if (!width || !height) return;
692	        renderer.setSize(width, height, false);
693	        camera.top = 1.2 * height / width;
694	        camera.bottom = -camera.top;
695	        camera.updateProjectionMatrix();
696	        if (prepared) render();
697	      };
698	      const observer = new ResizeObserver(resize);
699	      observer.observe(canvas);
700	      const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
701	      let elapsed = 0;
702	      let previousTime: number | undefined;
703	      const animate = (time: number) => {
704	        if (previousTime !== undefined) elapsed += (time - previousTime) / 1000;
705	        previousTime = time;
706	        preview.update(elapsed);
707	        render();
708	      };
709	      const updatePlayback = () => {
710	        previousTime = undefined;
711	        renderer.setAnimationLoop(prepared && playingRef.current && !reducedMotion.matches && !document.hidden ? animate : null);
712	        if (prepared) render();
713	      };
714	      updatePlaybackRef.current = updatePlayback;
715	      reducedMotion.addEventListener("change", updatePlayback);
716	      document.addEventListener("visibilitychange", updatePlayback);
717	
718	      const fail = (error: unknown) => {
719	        if (!disposed) {
720	          console.warn("Unable to load the decorative petri dish", error);
721	          onReady(true);
722	        }
723	      };
724	      new GLTFLoader().load("/models/petri-dish.glb", ({ scene: model }) => {
725	        dish = model.children[0] as Mesh;
726	        if (disposed) {
727	          disposeDish(dish);
728	          return;
729	        }
730	        dish.geometry.center();
731	        dish.geometry.computeBoundingBox();
732	        const size = dish.geometry.boundingBox!.getSize(new Vector3());
733	        dish.scale.setScalar(2 / size.x);
734	        const glass = dish.material as MeshPhysicalMaterial;
735	        glass.opacity = 0.45;
736	        glass.roughness = 0.08;
737	        glass.envMapIntensity = 1.2;
738	        glass.depthWrite = false;
739	        rim.position.z = size.z / size.x + 0.002;
740	        plate.add(dish, worm, rim);
741	        resize();
742	        void renderer.compileAsync(scene, camera).then(async () => {
743	          if (disposed) return;
744	          // Warm transmission targets and texture uploads while the intro is still hidden.
745	          render();
746	          await document.fonts.ready;
747	          if (disposed) return;
748	          prepared = true;
749	          updatePlayback();
750	          onReady(true);
751	        }).catch(fail);
752	      }, undefined, fail);
753	
754	      cleanup = () => {
755	        disposed = true;
756	        updatePlaybackRef.current = () => {};
757	        renderer.setAnimationLoop(null);
758	        reducedMotion.removeEventListener("change", updatePlayback);
759	        document.removeEventListener("visibilitychange", updatePlayback);
760	        observer.disconnect();
761	        if (dish) disposeDish(dish);
762	        disposeDish(rim);
763	        disposeDish(worm);
764	        environment.dispose();
765	        renderer.dispose();
766	      };
767	    });
768	    return () => {
769	      cancelAnimationFrame(startFrame);
770	      cleanup?.();
771	    };
772	  }, [onReady]);
773	
774	  return <canvas ref={canvasRef} className="home-petri-canvas" />;
775	}
