("""export default memo(function NeuronCanvas(props: Props) {
  return (""","""export default memo(function NeuronCanvas(props: Props) {
  // The Sketchfab model; the procedural neuron is the fallback so the stage is never empty.
  const [data, setData] = useState<NeuronData | null>(null)
