  const { size, camera, gl } = useThree()
  const glow = useMemo(glowTexture, [])
  const neuron = useMemo(() => new NeuronSim(data, { glow, autoInterval: reducedMotion ? 0 : 2.6 }), [data, glow, reducedMotion])
  const outer = useRef<THREE.Group>(null)
  const spin = useRef<THREE.Group>(null)
  /** Drag-to-rotate + wheel zoom state. Plain refs: no re-render per pointer move. */
  const drag = useRef({ active: false, x: 0, y: 0, moved: 0, yaw: 0, pitch: 0, vYaw: 0, vPitch: 0, zoom: 1 })

  // Pivot around the middle of the cell, not the soma.
  const centre = useMemo(() => {
    const box = new THREE.Box3()
    for (const geo of [data.soma, data.dendrites, data.axon, data.myelin]) {
      if (!geo.attributes.position) continue
      geo.computeBoundingBox()
      box.union(geo.boundingBox!)
    }
    return box.getCenter(new THREE.Vector3())
  }, [data])

  useEffect(() => {
    const v = new THREE.Vector3()
    neuron.onSpike = () => {
      neuron.group.getWorldPosition(v).project(camera)
      onSpike((v.x + 1) / 2, (1 - v.y) / 2)
    }
  }, [neuron, camera, onSpike])

  useEffect(() => () => { neuron.dispose(); glow.dispose() }, [neuron, glow])

  useEffect(() => {
    const el = gl.domElement
    const d = drag.current
    el.style.touchAction = 'none'
    el.style.cursor = 'grab'
    const down = (e: PointerEvent) => {
      d.active = true
      d.x = e.clientX
      d.y = e.clientY
      d.moved = 0
      d.vYaw = d.vPitch = 0
      el.style.cursor = 'grabbing'
    }
    const move = (e: PointerEvent) => {
      if (!d.active) return
      const dx = e.clientX - d.x
      const dy = e.clientY - d.y
      d.x = e.clientX
      d.y = e.clientY
      d.moved += Math.abs(dx) + Math.abs(dy)
      d.vYaw = dx * 0.006
      d.vPitch = dy * 0.006
      d.yaw += d.vYaw
      d.pitch = THREE.MathUtils.clamp(d.pitch + d.vPitch, -1.3, 1.3)
    }
    const up = () => {
      if (!d.active) return
      d.active = false
      el.style.cursor = 'grab'
    }
    const wheel = (e: WheelEvent) => {
      e.preventDefault()
      d.zoom = THREE.MathUtils.clamp(d.zoom * Math.exp(-e.deltaY * 0.0012), 0.6, 1.8)
    }
    el.addEventListener('pointerdown', down)
    window.addEventListener('pointermove', move)
    window.addEventListener('pointerup', up)
    window.addEventListener('pointercancel', up)
    el.addEventListener('wheel', wheel, { passive: false })
    return () => {
      el.removeEventListener('pointerdown', down)
      window.removeEventListener('pointermove', move)
      window.removeEventListener('pointerup', up)
      window.removeEventListener('pointercancel', up)
      el.removeEventListener('wheel', wheel)
    }
  }, [gl])

  // Title + button sit bottom-left (card.io layout), so the cell takes the upper right.
  const wide = size.width / size.height > 1.1
  const layout = wide
    ? { soma: [-0.2, 1.2, 0] as const, tilt: -0.12, scale: 0.86 }
    : { soma: [-1.5, 4.5, 0] as const, tilt: -0.5, scale: 0.42 }
  // Same framing as before: place the cell's centre where the old soma layout put it.
  const anchor = centre.clone().applyAxisAngle(new THREE.Vector3(0, 0, 1), layout.tilt).multiplyScalar(layout.scale).add(new THREE.Vector3(...layout.soma))

  useFrame((state, delta) => {
    neuron.setPointScale((state.size.height * state.viewport.dpr) / (2 * Math.tan((FOV * Math.PI) / 360)))
    neuron.update(Math.min(delta, 0.05), progressRef.current ?? 0)
    const d = drag.current
    if (!d.active && !reducedMotion) {
      // Let a flick coast to a stop.
      d.yaw += d.vYaw
      d.pitch = THREE.MathUtils.clamp(d.pitch + d.vPitch, -1.3, 1.3)
      d.vYaw *= 0.93
      d.vPitch *= 0.93
    }
    const sway = reducedMotion ? 0 : Math.sin(state.clock.elapsedTime * 0.16) * 0.2
    if (spin.current) {
      spin.current.rotation.y = d.yaw + sway
      spin.current.rotation.x = d.pitch
    }
    if (outer.current) {
      const target = layout.scale * d.zoom
      const s = outer.current.scale.x + (target - outer.current.scale.x) * 0.15
      outer.current.scale.setScalar(s)
    }
  })

  return (
    <group ref={outer} position={anchor} scale={layout.scale}>
      <group ref={spin}>
        <group rotation={[0, 0, layout.tilt]}>
          <group position={centre.clone().negate()}>
            <primitive object={neuron.group} />
            {/* Generous invisible hit target around the soma: click (not drag) to fire. */}
            <mesh
              onClick={(e) => {
                e.stopPropagation()
                if (drag.current.moved < 6) neuron.fire()
              }}
              onPointerOver={() => {
                if (!drag.current.active) gl.domElement.style.cursor = 'pointer'
              }}
              onPointerOut={() => {
                if (!drag.current.active) gl.domElement.style.cursor = 'grab'
              }}
            >
              <sphereGeometry args={[2, 16, 12]} />
              <meshBasicMaterial visible={false} />
            </mesh>
          </group>
        </group>
      </group>
    </group>
  )
}

