const MODEL_SIZE = 2.5;
const VIEW_SCALE = 8;
const OPACITY = 0.5;
const DNA_COLOR = 0x606060; // neutral dark grey
const VIEW_TILT_DEG = 30;
const AUTO_ROTATE_SPEED = 3;

