@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

/* Callio Labs' light, monochrome tokens. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0 / 0.72); /* frosted over the dither field */
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.48 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --chart-1: oklch(0.809 0.105 251.813);
  --chart-2: oklch(0.623 0.214 259.815);
  --chart-3: oklch(0.546 0.245 262.881);
  --chart-4: oklch(0.488 0.243 264.376);
  --chart-5: oklch(0.424 0.199 265.638);
  --radius: 0.625rem;
  --sidebar: oklch(1 0 0 / 0.55);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0 0 0 / 0.08);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0 0 0 / 0.1);
  --sidebar-ring: oklch(0.708 0 0);

  /* status, always paired with a text label */
  --status-flag: oklch(0.577 0.245 27.325);
  --status-watch: oklch(0.62 0.15 65);
  --status-stable: oklch(0.48 0 0);
}

@theme inline {
  --font-sans: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --font-heading: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --font-brand: "Callio", "Geist Variable", sans-serif;
  --font-serif-display: "Synonym", Georgia, serif;
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-foreground: var(--foreground);
  --color-background: var(--background);
  --color-flag: var(--status-flag);
  --color-watch: var(--status-watch);
  --color-stable: var(--status-stable);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

/* Callio: Chillax Semibold (Fontshare FFL, public/fonts/chillax/LICENSE.txt). */
@font-face {
  font-family: "Callio";
  src: url("/fonts/chillax/Chillax-Semibold.woff2") format("woff2"), url("/fonts/chillax/Chillax-Semibold.woff") format("woff");
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Synonym";
  src: url("/fonts/Synonym-Regular.otf") format("opentype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@layer base {
  * { @apply border-border outline-ring/50; }
  html, body, #root { height: 100%; }
  body {
    @apply bg-background text-foreground font-sans antialiased;
    margin: 0;
    overflow: hidden;
  }
}

@layer components {
  .font-brand { font-family: var(--font-brand); font-weight: 600; }
  .font-serif-display { font-family: var(--font-serif-display); font-weight: 400; }

  .eyebrow {
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--muted-foreground);
  }

  /* Frosted panels over the dither field. */
  [data-slot="sidebar-inner"], [data-slot="card"] {
    backdrop-filter: blur(14px) saturate(1.2);
    -webkit-backdrop-filter: blur(14px) saturate(1.2);
  }
}

/* Callio Labs splash. */
@keyframes splash-fade-out { from { opacity: 1; } to { opacity: 0; } }
.animate-splash-fade-out { animation: splash-fade-out 0.5s ease-out forwards; }

@keyframes loading-dot {
  0%, 80%, 100% { opacity: 0.3; transform: scale(0.8); }
  40% { opacity: 1; transform: scale(1); }
}
.animate-loading-dot-1 { animation: loading-dot 1.2s ease-in-out infinite; }
.animate-loading-dot-2 { animation: loading-dot 1.2s ease-in-out 0.15s infinite; }
.animate-loading-dot-3 { animation: loading-dot 1.2s ease-in-out 0.3s infinite; }

@media (prefers-reduced-motion: reduce) {
  .animate-loading-dot-1, .animate-loading-dot-2, .animate-loading-dot-3 { animation: none; }
  .animate-splash-fade-out { animation-duration: 1ms; }
}

